# SAFE-MODE: no real phishing, PowerShell, lateral movement or cloud auth is
# performed. Every signal is a labelled marker record; the labels are the whole
# point, so they are written BEFORE the corpus they describe.
set -euo pipefail
D=/tmp/cortexsim-mp021
RUN_TAG="${CORTEXSIM_RUN_TAG:-MP021}"
PRINCIPAL="${COMPROMISED_PRINCIPAL:-jdoe@corp.local}"
mkdir -p "$D"
# (0) ground-truth manifest — author-time labels, one row per emitted signal class
cat > "$D/manifest.ndjson" <<EOF
{"run_tag":"$RUN_TAG","signal_class":"phish_link_click","cortexsim_label":"malicious","principal":"$PRINCIPAL"}
{"run_tag":"$RUN_TAG","signal_class":"office_encoded_powershell","cortexsim_label":"malicious","principal":"$PRINCIPAL"}
{"run_tag":"$RUN_TAG","signal_class":"smb_rdp_fanout","cortexsim_label":"malicious","principal":"$PRINCIPAL"}
{"run_tag":"$RUN_TAG","signal_class":"cloud_admin_assume","cortexsim_label":"malicious","principal":"$PRINCIPAL"}
{"run_tag":"$RUN_TAG","signal_class":"backup_envelope_deviation","cortexsim_label":"hard_positive","principal":"svc-backup@corp.local"}
{"run_tag":"$RUN_TAG","signal_class":"authenticated_scanner_sweep","cortexsim_label":"benign","principal":"svc-scanner@corp.local"}
{"run_tag":"$RUN_TAG","signal_class":"sanctioned_admin_module_load","cortexsim_label":"benign","principal":"admin-sanctioned@corp.local"}
{"run_tag":"$RUN_TAG","signal_class":"rmm_patch_fanout","cortexsim_label":"benign","principal":"svc-rmm@corp.local"}
{"run_tag":"$RUN_TAG","signal_class":"in_window_backup","cortexsim_label":"benign","principal":"svc-backup@corp.local"}
EOF
echo "cortexsim-mp021-manifest-published rows=$(wc -l < "$D/manifest.ndjson")"
echo cortexsim-mp021-labelled-corpus-emitted
